 CREATE OR REPLACE FUNCTION public.getprovidercomplaintnotesdetails(provider_complaintid uuid, pagenumber integer, pagelimit integer)                                                                                                                                                                                                                                                                                  
  RETURNS TABLE(totalcount bigint, provider_complaint_notesid uuid, complaint_notes_date timestamp without time zone, complaint_notes_method_of_contact character varying, complaint_notes_note text, insertedby character varying, updateby character varying, complaint_contacts_name character varying, inserted_on timestamp without time zone, updated_on timestamp without time zone, include_in_summary boolean)
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                     
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                                                                                                                                                                     
 DECLARE                                                                                                                                                                                                                                                                                                                                                                                                             
 v_pageoffset int;                                                                                                                                                                                                                                                                                                                                                                                                   
 v_pagenumber int;                                                                                                                                                                                                                                                                                                                                                                                                   
 v_pagelimit int;                                                                                                                                                                                                                                                                                                                                                                                                    
 v_limit int;                                                                                                                                                                                                                                                                                                                                                                                                        
  totalcount integer;                                                                                                                                                                                                                                                                                                                                                                                                
  v_provider_complaintid uuid;                                                                                                                                                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                                                                                                                                     
  BEGIN                                                                                                                                                                                                                                                                                                                                                                                                              
  v_limit=10;                                                                                                                                                                                                                                                                                                                                                                                                        
     v_pagenumber := pageNumber-1;                                                                                                                                                                                                                                                                                                                                                                                   
     v_pageoffset = v_pagenumber * v_limit;                                                                                                                                                                                                                                                                                                                                                                          
 v_provider_complaintid:=provider_complaintid;                                                                                                                                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                                                                                                                                                                     
  RETURN QUERY                                                                                                                                                                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                                                                                                                                                                     
         select count(1) OVER() totalcount, pcc.provider_complaint_notesid,pcc.complaint_notes_date,                                                                                                                                                                                                                                                                                                                 
 pcc.complaint_notes_method_of_contact,pcc.complaint_notes_note ,cast(up.firstname || ' ' || up.lastname as character varying) as insertedby,                                                                                                                                                                                                                                                                        
 cast(up1.firstname || ' ' || up1.lastname as character varying) as updatedby,                                                                                                                                                                                                                                                                                                                                       
 pc.complaint_contacts_name,pcc.inserted_on,pcc.updated_on, pcc.include_in_summary                                                                                                                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                                                                                                                                                                                     
  from tb_provider_complaint_notes pcc                                                                                                                                                                                                                                                                                                                                                                               
             join tb_provider_complaint_contacts pc on pc.provider_complaint_contactsid=pcc.provider_complaint_contactsid and pc.activeflag=1                                                                                                                                                                                                                                                                        
                         join userprofile up on up.securityusersid=pcc.inserted_by and up.activeflag=1                                                                                                                                                                                                                                                                                                               
                         join userprofile up1 on up1.securityusersid=pcc.updated_by and up1.activeflag=1                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                     
                         where pc.provider_complaintid=v_provider_complaintid and pcc.activeflag=1                                                                                                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                                                                                                                                                                                     
         LIMIT v_limit OFFSET v_pageoffset ;                                                                                                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                                                                                                                                     
 end                                                                                                                                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                                                                                                     
 $function$                                                                                                                                                                                                                                                                                                                                                                                                            

